/** Responsive WebP derivatives generated by `npm run images:build`. */

const DEFAULT_WIDTHS = [480, 800, 1600] as const;

export function webpSrcSet(jpg: string | null | undefined, widths: readonly number[] = DEFAULT_WIDTHS): string | undefined {
  if (!jpg || !jpg.endsWith('.jpg')) return undefined;
  const base = jpg.slice(0, -4);
  return widths.map((width) => `${base}-${width}.webp ${width}w`).join(', ');
}
